using System;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using PeerChatDesktop;
public static class ConnectionPreviewUiTest {
    static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
    static void Check(bool value,string reason){if(!value)throw new Exception("Connection preview: "+reason);}
    static System.Collections.Generic.IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
    static T Find<T>(Window window,string name)where T:FrameworkElement{return Walk(window).OfType<T>().Single(e=>e.Name==name);}
    static void Select(ComboBox selector,string value){selector.SelectedItem=selector.Items.Cast<ComboBoxItem>().Single(i=>Convert.ToString(i.Tag)==value);}
    public static bool Run(DesktopApplication desktop,string directory){
        var zone=TimeZoneInfo.FindSystemTimeZoneById("Central Standard Time");
        var first=new DateTime(2026,11,1,6,30,0,DateTimeKind.Utc);var second=first.AddHours(1);
        Check(ConnectionPreviewDisplay.Local(first,zone).Contains("01:30:00 -05:00")&&ConnectionPreviewDisplay.Local(second,zone).Contains("01:30:00 -06:00"),"DST repeated hour retains offsets");
        Check(ConnectionPreviewDisplay.Local(new DateTime(2026,3,8,7,59,59,DateTimeKind.Utc),zone).Contains("01:59:59 -06:00")&&ConnectionPreviewDisplay.Local(new DateTime(2026,3,8,8,0,0,DateTimeKind.Utc),zone).Contains("03:00:00 -05:00"),"DST spring jump");
        Check(ConnectionPreviewDisplay.Local(first)==ConnectionPreviewDisplay.Local(first,TimeZoneInfo.Local),"Windows local timezone default");
        var longEvent=new ConnectionPreviewEvent{TimestampUtc=first,SessionId=new string('s',80),AttemptId=new string('a',80),CorrelationId=new string('c',80),Description=new string('x',2000)+" Unicode Ω",Type=ConnectionPreviewEventType.TLS};
        Check(longEvent.Summary.Length<650&&!longEvent.Summary.Contains(longEvent.SessionId)&&longEvent.DetailsUtc.Contains(longEvent.SessionId)&&longEvent.DetailsUtc.Contains(longEvent.Description),"bounded rows preserve full identifiers and description");
        Check(longEvent.UtcTimestamp.Contains("2026-11-01T06:30:00.0000000Z"),"exact UTC tooltip");
        var ordered=new ConnectionPreviewSnapshot{Events=new[]{new ConnectionPreviewEvent{TimestampUtc=second},new ConnectionPreviewEvent{TimestampUtc=first}}};Check(ConnectionPreviewQuery.Filter(ordered,"All","All","All")[0].TimestampUtc==first,"sort uses timestamps, not repeated local strings");
        typeof(DesktopApplication).GetField("connectionsDeveloperPreview",Flags).SetValue(desktop,true);        var provider=new SampleConnectionPreviewProvider();foreach(ConnectionPreviewState state in Enum.GetValues(typeof(ConnectionPreviewState))){var snap=provider.Read(state);Check(ConnectionPreviewQuery.Export(snap).StartsWith("SAMPLE"),"marked export");Check(snap.Sessions.Length<=3&&snap.Events.Length<=16,"bounded fixtures");Check(snap.Network.Last().Metrics.All(m=>m.Value=="N/A"),"unavailable measurements");if(state==ConnectionPreviewState.Empty||state==ConnectionPreviewState.Loading||state==ConnectionPreviewState.Unavailable)Check(snap.Sessions.Length==0&&snap.Failures.Length==0&&snap.Events.Length==0,"empty states");}
        var active=provider.Read(ConnectionPreviewState.Connected);Check(ConnectionPreviewQuery.Filter(active,"Error","All","All").All(e=>e.Severity==ConnectionPreviewSeverity.Error),"severity filter");Check(ConnectionPreviewQuery.Filter(active,"All","TLS","All").All(e=>e.Type==ConnectionPreviewEventType.TLS),"type filter");Check(ConnectionPreviewQuery.Logs(active,"TLS",true).Contains("type=TLS"),"structured search");Check(ConnectionPreviewQuery.Logs(active,"TLS",false).StartsWith("SAMPLE"),"search sample marking");
        string complete=ConnectionPreviewQuery.Export(active);Check(active.Sessions.All(s=>complete.Contains(s.Id)&&complete.Contains(ConnectionPreviewDisplay.Utc(s.StartedUtc)))&&active.Failures.All(f=>complete.Contains(f.Id))&&active.Events.All(e=>complete.Contains(e.SessionId)&&complete.Contains(e.AttemptId)&&complete.Contains(e.CorrelationId)&&complete.Contains(ConnectionPreviewDisplay.Utc(e.TimestampUtc))),"exports preserve all full identifiers and exact UTC values");
        typeof(DesktopApplication).GetMethod("OpenContextDiagnostics",Flags).Invoke(desktop,new object[]{DiagnosticSection.Connections,""});var window=(Window)typeof(DesktopApplication).GetField("groupDiagnosticWindow",Flags).GetValue(desktop);var tabs=(TabControl)typeof(DesktopApplication).GetField("groupDiagnosticTabs",Flags).GetValue(desktop);var statePicker=(ComboBox)typeof(DesktopApplication).GetField("connectionPreviewExamples",Flags).GetValue(desktop);Check(statePicker.Visibility==Visibility.Visible&&statePicker.Items.Count==11,"state picker");
        foreach(ConnectionPreviewState state in Enum.GetValues(typeof(ConnectionPreviewState))){statePicker.SelectedIndex=(int)state;foreach(TabItem tab in tabs.Items){tabs.SelectedItem=tab;window.UpdateLayout();Check(tab.Content!=null,"state tab content");}Check(((string)typeof(DesktopApplication).GetMethod("CurrentDiagnosticExport",Flags).Invoke(desktop,null)).StartsWith("SAMPLE"),"shared export marking");}
        statePicker.SelectedIndex=0;window.Width=1180;window.Height=900;
        Check(Walk(window).OfType<TextBlock>().Any(t=>t.Text=="Preview State")&&Walk(window).OfType<TextBlock>().Any(t=>t.Text.Contains("Simulated · not live")),"explicit preview-state label");
        var footer=((DockPanel)window.Content).Children.OfType<WrapPanel>().Single();var pause=footer.Children.OfType<Button>().Single(b=>Object.Equals(b.Tag,"Pause graphs"));Check(!pause.IsEnabled&&pause.ToolTip.ToString().Contains("No live graphs")&&ToolTipService.GetShowOnDisabled(pause),"preview footer explains disabled graph pause");Check(footer.Children.OfType<Button>().Single(b=>Object.Equals(b.Tag,"Copy Diagnostics")).Content.ToString().Contains("sample"),"sample footer export label");
        foreach(TabItem tab in tabs.Items){tabs.SelectedItem=tab;window.UpdateLayout();string name=Convert.ToString(tab.Header);
            if(name=="Sessions"){var list=Find<ListBox>(window,"ConnectionSessions");list.SelectedIndex=2;window.UpdateLayout();Check(Walk(window).OfType<TextBox>().Any(t=>t.Text.Contains("Historical group control session")&&t.Text.Contains("sample-session-001")&&t.Text.Contains("Start UTC:")&&t.Text.Contains("Local start:")),"session selection with copyable local/UTC details");}
            if(name=="Failures"){var list=Find<ListBox>(window,"ConnectionFailures");list.SelectedIndex=1;window.UpdateLayout();var detail=Find<Expander>(window,"ConnectionFailureDetails");detail.IsExpanded=false;detail.IsExpanded=true;window.UpdateLayout();Check(((TextBox)detail.Content).Text.Contains("sample-failure-001")&&((TextBox)detail.Content).Text.Contains("Time UTC:"),"failure selection and expansion");}
            if(name=="Events"){Select(Find<ComboBox>(window,"EventSeverity"),"Error");window.UpdateLayout();Check(Find<ListBox>(window,"ConnectionEvents").Items.Count==1,"UI severity filter");Select(Find<ComboBox>(window,"EventSeverity"),"All");Select(Find<ComboBox>(window,"EventType"),"TLS");window.UpdateLayout();Check(Find<ListBox>(window,"ConnectionEvents").Items.Count>=1,"UI type filter");Select(Find<ComboBox>(window,"EventType"),"All");Select(Find<ComboBox>(window,"EventSession"),"sample-session-003");window.UpdateLayout();Check(Find<ListBox>(window,"ConnectionEvents").Items.Cast<ConnectionPreviewEvent>().All(e=>e.SessionId=="sample-session-003"),"UI session filter");Select(Find<ComboBox>(window,"EventSession"),"All");}
            if(name=="Raw Logs"){var search=Find<TextBox>(window,"ConnectionLogSearch");search.Text="TLS";window.UpdateLayout();Check(Find<TextBox>(window,"ConnectionRawLogs").Text.Contains("TLS"),"UI search");Select(Find<ComboBox>(window,"ConnectionLogPresentation"),"Structured");window.UpdateLayout();Check(Find<TextBox>(window,"ConnectionRawLogs").Text.Contains("type=TLS"),"UI structured mode");search.Text="";}
            window.UpdateLayout();
            if(name=="Events"){var list=Find<ListBox>(window,"ConnectionEvents");list.SelectedIndex=4;var selected=(ConnectionPreviewEvent)list.SelectedItem;var detail=Find<Expander>(window,"ConnectionEventDetails");detail.IsExpanded=true;window.UpdateLayout();Check(((TextBox)detail.Content).Text.Contains(selected.SessionId)&&((TextBox)detail.Content).Text.Contains(selected.AttemptId)&&((TextBox)detail.Content).Text.Contains(selected.CorrelationId)&&((TextBox)detail.Content).Text.Contains("UTC:"),"event expansion preserves IDs and UTC");var page=(ScrollViewer)((TabItem)tabs.SelectedItem).Content;page.ScrollToEnd();window.UpdateLayout();}
            if(name=="Events")Check(Walk(Find<ListBox>(window,"ConnectionEvents")).OfType<TextBlock>().Any(t=>t.Text.Contains("lifecycle example")),"rendered event rows");
            var surface=(FrameworkElement)window.Content;var bmp=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(surface.ActualWidth),(int)Math.Ceiling(surface.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var context=drawing.RenderOpen())context.DrawRectangle(new VisualBrush(surface),null,new Rect(0,0,surface.ActualWidth,surface.ActualHeight));bmp.Render(drawing);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bmp));using(var file=System.IO.File.Create(System.IO.Path.Combine(directory,"Connections-"+name.Replace(" ","")+".png")))png.Save(file);
        }
        window.Close();
        typeof(DesktopApplication).GetMethod("OpenContextDiagnostics",Flags).Invoke(desktop,new object[]{DiagnosticSection.GroupCalls,""});window=(Window)typeof(DesktopApplication).GetField("groupDiagnosticWindow",Flags).GetValue(desktop);var projection=(GroupTelemetryProjection)typeof(DesktopApplication).GetField("groupTelemetry",Flags).GetValue(desktop);var samples=(System.Collections.Generic.Queue<GroupTelemetryProjection>)typeof(DesktopApplication).GetField("groupSamples",Flags).GetValue(desktop);projection.VoiceActive=true;samples.Enqueue(new GroupTelemetryProjection{UploadMbps=1});typeof(DesktopApplication).GetMethod("RefreshDiagnosticFooter",Flags).Invoke(desktop,null);footer=((DockPanel)window.Content).Children.OfType<WrapPanel>().Single();pause=footer.Children.OfType<Button>().Single(b=>Object.Equals(b.Tag,"Pause graphs"));Check(pause.IsEnabled,"live group graph pause available");pause.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((bool)typeof(DesktopApplication).GetField("graphsPaused",Flags).GetValue(desktop),"group graph pause retained");pause.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!(bool)typeof(DesktopApplication).GetField("graphsPaused",Flags).GetValue(desktop),"group graph resume retained");window.Close();Console.WriteLine("PASS: Connections preview label, bounded IDs/full details, local/UTC/DST timestamps, filters, context footer and live group graph pause/resume.");return true;
    }
}
